-- Inserido imediatamente antes do finish() do experimento de seis buckets.
-- Requer fixtures sintéticas, gates e ACLs abertos SOMENTE na transação externa.
reset role;
update config.usuarios set ativo=false where user_id='16891000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok(format('insert into storage.objects(id,bucket_id,name,owner_id) values (%L,%L,%L,%L)',
 id,bucket,nome,'16891000-0000-4000-8000-000000000001'),
 '42501',null,'usuário revogado não insere: ' || bucket)
from (values
 ('16891000-0000-4000-8000-000000000091','sso-grupos-fotos','16891000-0000-4000-8000-000000000002/16891000-0000-4000-8000-000000000006/16891000-0000-4000-8000-000000000098'),
 ('16891000-0000-4000-8000-000000000092','sso-material-evidencias','16891000-0000-4000-8000-000000000002/16891000-0000-4000-8000-000000000051/2/16891000-0000-4000-8000-000000000098'),
 ('16891000-0000-4000-8000-000000000093','sso-levantamento-fotos','16891000-0000-4000-8000-000000000002/16891000-0000-4000-8000-000000000050/16891000-0000-4000-8000-000000000098'),
 ('16891000-0000-4000-8000-000000000094','sso-levantamento-documentos','16891000-0000-4000-8000-000000000002/16891000-0000-4000-8000-000000000050/16891000-0000-4000-8000-000000000098'),
 ('16891000-0000-4000-8000-000000000095','sso-retorno-evidencias','16891000-0000-4000-8000-000000000002/16891000-0000-4000-8000-000000000018/16891000-0000-4000-8000-000000000098'),
 ('16891000-0000-4000-8000-000000000096','sso-despesas-visita','16891000-0000-4000-8000-000000000002/16891000-0000-4000-8000-000000000054/16891000-0000-4000-8000-000000000098')
) t(id,bucket,nome);
reset role;
